    /**
     * Tests creating a new BankAccount.
     *
     * @return    BankAccount
     */
    public BankAccount testCreate() throws Throwable {
    BankAccount entity = null;

    LOGGER.info( "BankAccountTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a BankAccount");

    StringBuilder msg = new StringBuilder( "-- Failed to create a BankAccount" );

    try {
        entity = service.createBankAccount( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getBankAccountId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a BankAccount with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a BankAccount.
     *
     * @return    BankAccount
     */
    public BankAccount testRead() throws Throwable {
    LOGGER.info( "BankAccountTest:testRead()" );
    LOGGER.info( "-- Reading a previously created BankAccount" );

    BankAccount entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read BankAccount with primary key" );
    msg.append( theId );

    try {
        entity = service.getBankAccount( new BankAccountFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getBankAccountId();

        LOGGER.info( "-- Successfully found BankAccount " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a BankAccount.
     *
     * @return    BankAccount
     */
    public BankAccount testUpdate() throws Throwable {
    LOGGER.info( "BankAccountTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a BankAccount." );

    StringBuilder msg = new StringBuilder( "Failed to update a BankAccount : " );
    BankAccount entity = null;

    try {
        UpdateBankAccountCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setBankAccountId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created BankAccount." );

        entity = service.updateBankAccount( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved BankAccount - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a BankAccount.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "BankAccountTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created BankAccount." );

    try {
        DeleteBankAccountCommand deleteCommand = new DeleteBankAccountCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted BankAccount with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete BankAccount with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all BankAccounts.
     *
     * @return    Collection
     */
    public List<BankAccount> testGetAll() throws Throwable {
    LOGGER.info( "BankAccountTest:testGetAll() - Retrieving Collection of BankAccounts:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all BankAccount : " );
    List<BankAccount> collection  = null;

    try {
        // call the static get method on the BankAccountService
        collection = service.getAllBankAccount();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            BankAccount currEntity  = null;
            Iterator<BankAccount> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getBankAccountId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

